  a_cop_ww: { de: "Ø COP Warmwasser", en: "avg COP hot water", fr: "COP moy. eau chaude", ja: "給湯 平均 COP" },
  a_cop_gesamt: { de: "Ø COP gesamt", en: "avg COP overall", fr: "COP moy. global", ja: "全体 平均 COP" },
  a_cop_minmax: { de: "min · max Heizen", en: "min · max heating", fr: "min · max chauffage", ja: "暖房 最小・最大" },
  a_t_ok: { de: "Taktung unauffällig", en: "Cycling looks fine", fr: "Cycles normaux", ja: "運転サイクルは正常" },
  a_t_einige: { de: "Einige kurze Läufe", en: "Some short runs", fr: "Quelques cycles courts", ja: "短い運転が少しあります" },
  a_t_viele: { de: "Viele kurze Läufe, Optimierung prüfen", en: "Many short runs, consider optimising", fr: "Nombreux cycles courts, optimisation à vérifier", ja: "短い運転が多く、最適化を検討してください" },
  a_t_starts: { de: "Viele Starts", en: "Many starts", fr: "Nombreux démarrages", ja: "起動回数が多い" },
  a_t_ok_d: { de: "{n} Starts, Ø {d} min Laufzeit, keine Läufe unter 10 min", en: "{n} starts, avg {d} min run time, no runs under 10 min", fr: "{n} démarrages, durée moy. {d} min, aucun cycle de moins de 10 min", ja: "起動 {n} 回、平均運転 {d} 分、10分未満の運転なし" },
  a_t_kurz_d: { de: "{k} von {n} Läufen unter 10 min, davon {s} unter 6 min.", en: "{k} of {n} runs under 10 min, {s} of them under 6 min.", fr: "{k} cycles sur {n} de moins de 10 min, dont {s} de moins de 6 min.", ja: "{n} 回中 {k} 回が10分未満、そのうち {s} 回が6分未満。" },
  a_t_starts_d: { de: "Im Mittel {n} Starts pro Tag liegen über rund 15 Starts pro Tag, ab denen der Fraunhofer-Feldtest im Jahresmittel eine Prüfung nahelegt.", en: "An average of {n} starts per day is above about 15 starts per day, the annual average from which the Fraunhofer field test suggests a check.", fr: "En moyenne {n} démarrages par jour dépassent environ 15 démarrages par jour, moyenne annuelle à partir de laquelle l'essai de terrain Fraunhofer conseille une vérification.", ja: "1日平均 {n} 回の起動は、Fraunhofer の実地試験で年間平均として点検が勧められる1日約15回を超えています。" },
  a_t_rat: { de: "Hinweis: Heizkurve oder Schaltdifferenz (Hysterese) prüfen, im Zweifel mit dem Fachbetrieb.", en: "Note: check the heating curve or the switching differential (hysteresis), if in doubt with your installer.", fr: "Conseil : vérifier la courbe de chauffe ou le différentiel de commutation (hystérésis), en cas de doute avec l'installateur.", ja: "ヒント：暖房曲線やスイッチング差（ヒステリシス）を確認してください。不明な場合は施工業者にご相談ください。" },
  a_t_quelle: { de: "Richtwerte: 10 bis 20 min Laufzeit je Start (Bundesverband Wärmepumpe), unter etwa 6 min sinkt die Effizienz; bis etwa 15 Starts pro Tag im Jahresmittel unauffällig (Fraunhofer WP-QS). Praxiswerte, keine Norm. Die Bewertung ist ein Hinweis, keine Diagnose.", en: "Guide values: 10 to 20 min run time per start (German Heat Pump Association), efficiency drops below about 6 min; up to about 15 starts per day on annual average is unremarkable (Fraunhofer WP-QS). Practical values, not a standard. The assessment is a hint, not a diagnosis.", fr: "Valeurs indicatives : 10 à 20 min de fonctionnement par démarrage (association allemande des pompes à chaleur), l'efficacité baisse en dessous d'environ 6 min ; jusqu'à environ 15 démarrages par jour en moyenne annuelle, rien d'anormal (Fraunhofer WP-QS). Valeurs pratiques, pas une norme. L'évaluation est une indication, pas un diagnostic.", ja: "目安：起動1回あたり運転10〜20分（ドイツヒートポンプ協会）、約6分未満では効率が低下。年間平均で1日約15回までの起動は問題なし（Fraunhofer WP-QS）。実務上の目安で規格ではありません。評価はヒントであり診断ではありません。" },
  a_t_starts_k: { de: "Starts", en: "starts", fr: "démarrages", ja: "起動" },
  a_t_lauf: { de: "Ø Laufzeit", en: "avg run time", fr: "durée moy.", ja: "平均運転時間" },
  a_t_pause: { de: "Ø Pause", en: "avg pause", fr: "pause moy.", ja: "平均停止時間" },
  a_t_kurz_k: { de: "Läufe unter 10 min", en: "runs under 10 min", fr: "cycles < 10 min", ja: "10分未満の運転" },
  a_t_laeufe: { de: "Läufe", en: "Runs", fr: "Cycles", ja: "運転" },
  a_t_stunde: { de: "Starts je Stunde, Farbe nach dem kürzesten Lauf", en: "Starts per hour, colour by the shortest run", fr: "Démarrages par heure, couleur selon le cycle le plus court", ja: "1時間あたりの起動回数（色は最短の運転）" },
  a_t_stunde_t: { de: "{n} Starts", en: "{n} starts", fr: "{n} démarrages", ja: "起動 {n} 回" },
