  a_t_l_kurz: { de: "6 bis 10 min", en: "6 to 10 min", fr: "6 à 10 min", ja: "6〜10分" },
  a_t_l_gut: { de: "10 bis 20 min", en: "10 to 20 min", fr: "10 à 20 min", ja: "10〜20分" },
  a_t_l_sehrgut: { de: "über 20 min", en: "over 20 min", fr: "plus de 20 min", ja: "20分超" },
  a_c_gut: { de: "COP besser als erwartet", en: "COP better than expected", fr: "COP meilleur que prévu", ja: "COP は想定より良好" },
  a_c_rahmen: { de: "COP im erwarteten Bereich", en: "COP within the expected range", fr: "COP dans la plage attendue", ja: "COP は想定の範囲内" },
  a_c_unter: { de: "COP unter Erwartung", en: "COP below expectation", fr: "COP inférieur aux attentes", ja: "COP は想定を下回る" },
  a_c_schlecht: { de: "COP deutlich unter Erwartung", en: "COP clearly below expectation", fr: "COP nettement inférieur aux attentes", ja: "COP は想定を大きく下回る" },
  a_c_unter_d: { de: "Ø {p} % des erwarteten COP bei Ø {a} °C außen und Ø {v} °C Vorlauf", en: "avg {p} % of the expected COP at avg {a} °C outdoor and {v} °C flow", fr: "moy. {p} % du COP attendu à {a} °C extérieur et {v} °C départ en moyenne", ja: "平均外気温 {a} °C・往き温度 {v} °C で想定 COP の平均 {p} %" },
  a_c_ohne_t: { de: "Keine Bewertung möglich", en: "No assessment possible", fr: "Évaluation impossible", ja: "評価できません" },
  a_c_ohne_d: { de: "Für die Bewertung werden Außen- und Vorlauftemperatur gebraucht.", en: "The assessment needs outdoor and flow temperature.", fr: "L'évaluation nécessite la température extérieure et la température de départ.", ja: "評価には外気温と往き温度が必要です。" },
  a_c_erwartet: { de: "erwartet {c}", en: "expected {c}", fr: "attendu {c}", ja: "想定 {c}" },
  a_c_erwartung: { de: "erwarteter COP", en: "expected COP", fr: "COP attendu", ja: "想定 COP" },
  a_c_l_gut: { de: "ab 100 % der Erwartung", en: "100 % of expectation or more", fr: "100 % de l'attendu ou plus", ja: "想定の100%以上" },
  a_c_l_rahmen: { de: "85 bis 100 %", en: "85 to 100 %", fr: "85 à 100 %", ja: "85〜100%" },
  a_c_l_unter: { de: "70 bis 85 %", en: "70 to 85 %", fr: "70 à 85 %", ja: "70〜85%" },
  a_c_l_schlecht: { de: "unter 70 %", en: "under 70 %", fr: "moins de 70 %", ja: "70%未満" },
  a_c_zaehl: { de: "{k} von {n} Läufen erreichen mindestens 85 % des bei ihrer Außen- und Vorlauftemperatur erwarteten COP.", en: "{k} of {n} runs reach at least 85 % of the COP expected at their outdoor and flow temperature.", fr: "{k} cycles sur {n} atteignent au moins 85 % du COP attendu à leur température extérieure et de départ.", ja: "{n} 回中 {k} 回の運転が、その外気温と往き温度での想定 COP の85%以上に達しています。" },
  a_c_nur_ww: { de: "Schwächer sind nur Warmwasserläufe. Beim Aufheizen des Speichers steigt der Vorlauf während des Laufs, das senkt den COP.", en: "Only hot water runs are weaker. While the tank heats up, the flow temperature rises during the run, which lowers the COP.", fr: "Seuls les cycles d'eau chaude sont plus faibles. Pendant la chauffe du ballon, la température de départ monte au cours du cycle, ce qui baisse le COP.", ja: "低いのは給湯運転のみです。タンク加熱中は運転中に往き温度が上がるため COP が下がります。" },
  a_c_rat: { de: "Hinweis: Ein niedrigerer Vorlauf (Heizkurve) hebt den COP; kurze Läufe und häufiges Abtauen senken ihn.", en: "Note: a lower flow temperature (heating curve) raises the COP; short runs and frequent defrosting lower it.", fr: "Conseil : une température de départ plus basse (courbe de chauffe) augmente le COP ; les cycles courts et les dégivrages fréquents le réduisent.", ja: "ヒント：往き温度を下げる（暖房曲線）と COP は上がり、短い運転や頻繁な霜取りは COP を下げます。" },
  a_c_quelle: { de: "Erwartung: Carnot-COP aus Außen- und Vorlauftemperatur mal Gütegrad 0,42. Der Gütegrad ist der Mittelwert, der sich aus den Datenblattwerten der Panasonic Aquarea T-CAP M 12 kW an den Prüfpunkten A7, A2 und A-7 mit W35 und W55 ergibt (0,38 bis 0,47); für reale Geräte werden rund 0,45 genannt (42watt). Die Stufen 85 % und 70 % sind eigene Festlegungen. Hinweis, keine Diagnose.", en: "Expectation: Carnot COP from outdoor and flow temperature times an efficiency factor of 0.42. This is the average derived from the datasheet values of the Panasonic Aquarea T-CAP M 12 kW at the rating points A7, A2 and A-7 with W35 and W55 (0.38 to 0.47); about 0.45 is quoted for real devices (42watt). The 85 % and 70 % levels are the card's own choice. A hint, not a diagnosis.", fr: "Attendu : COP de Carnot à partir des températures extérieure et de départ, multiplié par un rendement de 0,42. C'est la moyenne déduite des valeurs de la fiche technique de la Panasonic Aquarea T-CAP M 12 kW aux points A7, A2 et A-7 avec W35 et W55 (0,38 à 0,47) ; environ 0,45 est cité pour les appareils réels (42watt). Les seuils de 85 % et 70 % sont un choix propre à la carte. Indication, pas un diagnostic.", ja: "想定値：外気温と往き温度から求めたカルノー COP に効率係数 0.42 を掛けたもの。この係数は Panasonic Aquarea T-CAP M 12 kW のデータシート（A7・A2・A-7、W35・W55）から求めた平均値です（0.38〜0.47）。実機では約0.45とされています（42watt）。85%と70%の区切りはカード独自の設定です。診断ではなくヒントです。" },
  a_t_kalt: { de: "Kurze Läufe auch bei Kälte, Optimierung prüfen", en: "Short runs even in cold weather, consider optimising", fr: "Cycles courts même par temps froid, optimisation à vérifier", ja: "低温時にも短い運転があり、最適化を検討してください" },
  a_t_mild_t: { de: "Kurze Läufe in der Übergangszeit", en: "Short runs in mild weather", fr: "Cycles courts en mi-saison", ja: "中間期の短い運転" },
  a_t_kalt_d: { de: "{k} kurze Läufe bei unter 5 °C außen: Dort ist die Heizlast hoch und mit geringer Last nicht zu erklären, Schaltdifferenz, Heizkurve und Durchfluss prüfen.", en: "{k} short runs below 5 °C outdoor: the heat load is high there and cannot explain them, check switching differential, heating curve and flow rate.", fr: "{k} cycles courts sous 5 °C extérieur : la charge de chauffage y est élevée et ne les explique pas, vérifier différentiel, courbe de chauffe et débit.", ja: "外気温5 °C未満での短い運転が {k} 回：この温度では暖房負荷が高く負荷不足では説明できません。スイッチング差、暖房曲線、流量を確認してください。" },
  a_t_mild_d: { de: "{k} kurze Läufe ab 10 °C außen: In der Übergangszeit liegt die Heizlast oft unter der kleinsten Leistung der Wärmepumpe, kurze Läufe sind dort häufiger.", en: "{k} short runs from 10 °C outdoor: in mild weather the heat load is often below the heat pump's minimum output, short runs are more common there.", fr: "{k} cycles courts à partir de 10 °C extérieur : en mi-saison, la charge est souvent inférieure à la puissance minimale de la pompe à chaleur, les cycles courts y sont plus fréquents.", ja: "外気温10 °C以上での短い運転が {k} 回：中間期は暖房負荷がヒートポンプの最小出力を下回ることが多く、短い運転が増えます。" },
  a_t_baender: { de: "Nach Außentemperatur", en: "By outdoor temperature", fr: "Selon la température extérieure", ja: "外気温別" },
  a_t_b1: { de: "unter 0 °C", en: "below 0 °C", fr: "sous 0 °C", ja: "0 °C未満" },
  a_t_b2: { de: "0 bis 5 °C", en: "0 to 5 °C", fr: "0 à 5 °C", ja: "0〜5 °C" },
